    { "Show FPS", "FPS anzeigen", "Afficher les FPS", "Mostra FPS", "FPS 표시", "FPSを表示", "Показывать FPS", "显示 FPS", "Mostrar FPS", "Mostrar FPS", "Tampilkan FPS", "Tembongkeun FPS" },
