    { "Show time to level", "Zeit bis zum Level anzeigen", "Afficher le temps avant le niveau", "Mostra tempo al livello", "레벨까지 시간 표시", "レベルまでの時間を表示", "Показывать время до уровня", "显示升级所需时间", "Mostrar tempo até o nível", "Mostrar tiempo hasta el nivel", "Tampilkan waktu ke level", "Tembongkeun waktu ka level" },
    { "Show rested XP", "Erholte XP anzeigen", "Afficher l'XP reposé", "Mostra XP riposato", "휴식 XP 표시", "休息XPを表示", "Показывать XP отдыха", "显示充分休息的 XP", "Mostrar XP descansado", "Mostrar XP descansado", "Tampilkan XP istirahat", "Tembongkeun XP istirahat" },
    { "Show pet capped warning", "Warnung bei max. Pet anzeigen", "Afficher l'alerte familier plafonné", "Mostra avviso famiglio al limite", "펫 상한 경고 표시", "ペット上限の警告を表示", "Показывать предупреждение о питомце", "显示宠物封顶警告", "Mostrar aviso de mascote no limite", "Mostrar aviso de mascota al tope", "Tampilkan peringatan peliharaan mentok", "Tembongkeun peringatan piaraan mentok" },
    { "Show gold per hour", "Gold pro Stunde anzeigen", "Afficher l'or par heure", "Mostra oro all'ora", "시간당 골드 표시", "時間あたりのゴールドを表示", "Показывать золото в час", "显示每小时金币", "Mostrar ouro por hora", "Mostrar oro por hora", "Tampilkan emas per jam", "Tembongkeun emas per jam" },
    { "Ignore idle time", "Leerlaufzeit ignorieren", "Ignorer le temps d'inactivité", "Ignora tempo di inattività", "유휴 시간 무시", "待機時間を無視", "Не учитывать простой", "忽略闲置时间", "Ignorar tempo ocioso", "Ignorar tiempo inactivo", "Abaikan waktu diam", "Teu diitung waktu diam" },
    { "Level-up alert", "Levelaufstieg-Warnung", "Alerte de montée de niveau", "Avviso salita di livello", "레벨업 알림", "レベルアップの通知", "Оповещение о повышении уровня", "升级提醒", "Alerta de subida de nível", "Alerta de subida de nivel", "Peringatan naik level", "Peringatan naek level" },
    { "Alert when close to level", "Warnung kurz vor dem Level", "Alerte proche du niveau", "Avviso vicino al livello", "레벨 근접 시 알림", "レベル直前に通知", "Оповещение при близости к уровню", "接近升级时提醒", "Alerta perto do nível", "Alerta cerca del nivel", "Peringatan dekat level", "Peringatan deukeut level" },
    { "Alert at: %s", "Warnen bei: %s", "Alerte à : %s", "Avvisa a: %s", "알림 기준: %s", "通知のしきい値: %s", "Оповещать при: %s", "提醒阈值：%s", "Alertar em: %s", "Alertar a: %s", "Peringatan pada: %s", "Peringatan dina: %s" },
    { "Compact map", "Kompakte Karte", "Carte compacte", "Mappa compatta", "간단한 지도", "コンパクトマップ", "Компактная карта", "紧凑地图", "Mapa compacto", "Mapa compacto", "Peta ringkas", "Peta ringkes" },
    { "On: the progress bar under a waiting chip is white, then yellow and red as its timer drops (set the two warning times below). Off: it keeps the status colour.", "An: Der Fortschrittsbalken unter einem wartenden Chip ist weiß, dann gelb und rot, wenn sich der Timer verringert (die beiden Warnzeiten unten einstellen). Aus: er behält die Statusfarbe bei.", "Activé : la barre de progression d'un chip en attente est blanche, puis jaune et rouge à mesure que le minuteur diminue (réglez les deux seuils ci-dessous). Désactivé : elle garde la couleur du statut.", "Attivo: la barra di avanzamento sotto un chip in attesa è bianca, poi gialla e rossa man mano che il timer scende (imposta le due soglie qui sotto). Disattivo: mantiene il colore dello stato.", "켜짐: 대기 중인 칩 아래 진행 막대는 타이머가 줄어들면서 흰색, 노란색, 빨간색으로 바뀝니다(아래 두 경고 시간을 설정). 꺼짐: 상태 색을 유지합니다.", "オン：待機中のチップの下の進行バーは、タイマーが減るにつれて白、黄、赤に変わります（下の2つの警告時間を設定）。オフ：ステータスの色のままです。", "Вкл.: полоса прогресса под ожидающим чипом сначала белая, затем жёлтая и красная по мере уменьшения таймера (две пороговые величины ниже). Выкл.: остаётся цвет статуса.", "开启：等待中的标签下方进度条会随计时减少从白色变为黄色再变为红色（在下方设置两个警告时间）。关闭：保持状态颜色。", "Ligado: a barra de progresso sob um chip em espera fica branca, depois amarela e vermelha conforme o timer diminui (defina os dois tempos de aviso abaixo). Desligado: mantém a cor do status.", "Activado: la barra de progreso bajo un chip en espera es blanca, luego amarilla y roja a medida que baja el temporizador (ajusta los dos tiempos de aviso abajo). Desactivado: mantiene el color del estado.", "Aktif: bilah kemajuan di bawah chip yang menunggu berwarna putih, lalu kuning dan merah saat timer turun (atur dua waktu peringatan di bawah). Nonaktif: tetap memakai warna status.", "Aktif: bilah kamajuan handapeun chip nu ngantosan bodas, terus konéng jeung beureum mungkas timer turun (atur dua waktu peringatan di handap). Nonaktif: tetep make warna status." },
    { "The progress bar of a waiting group turns yellow when its timer is at or below this many seconds. Needs Urgency colors.", "Der Fortschrittsbalken einer wartenden Gruppe wird gelb, wenn der Timer bei oder unter dieser Anzahl Sekunden liegt. Benötigt Farben bei Dringlichkeit.", "La barre de progression d'un groupe en attente devient jaune quand son minuteur est à ce nombre de secondes ou moins. Nécessite les couleurs d'urgence.", "La barra di avanzamento di un gruppo in attesa diventa gialla quando il timer è pari o inferiore a questo numero di secondi. Richiede i colori di urgenza.", "대기 중인 그룹의 진행 막대는 타이머가 이 초 이하일 때 노란색이 됩니다. '긴급도 색상'이 필요합니다.", "待機中のグループの進行バーは、タイマーがこの秒数以下になると黄色になります。「緊急度の色」が必要です。", "Полоса прогресса ожидающей группы становится жёлтой, когда таймер не превышает это число секунд. Нужны «Цвета срочности».", "等待中的分组进度条在计时器不超过此秒数时变为黄色。需要开启“紧急程度颜色”。", "A barra de progresso de um grupo em espera fica amarela quando o timer está nesse número de segundos ou menos. Precisa de Cores de urgência.", "La barra de progreso de un grupo en espera se vuelve amarilla cuando el temporizador está en estos segundos o menos. Necesita Colores de urgencia.", "Bilah kemajuan grup yang menunggu berubah kuning saat timer sama dengan atau kurang dari jumlah detik ini. Perlu Warna urgensi.", "Bilah kamajuan grup nu ngantosan jadi konéng lamun timer sarua atawa kurang ti jumlah detik ieu. Perlu Warna urgénsi." },
    { "The progress bar of a waiting group turns red when its timer is at or below this many seconds. Needs Urgency colors.", "Der Fortschrittsbalken einer wartenden Gruppe wird rot, wenn der Timer bei oder unter dieser Anzahl Sekunden liegt. Benötigt Farben bei Dringlichkeit.", "La barre de progression d'un groupe en attente devient rouge quand son minuteur est à ce nombre de secondes ou moins. Nécessite les couleurs d'urgence.", "La barra di avanzamento di un gruppo in attesa diventa rossa quando il timer è pari o inferiore a questo numero di secondi. Richiede i colori di urgenza.", "대기 중인 그룹의 진행 막대는 타이머가 이 초 이하일 때 빨간색이 됩니다. '긴급도 색상'이 필요합니다.", "待機中のグループの進行バーは、タイマーがこの秒数以下になると赤になります。「緊急度の色」が必要です。", "Полоса прогресса ожидающей группы становится красной, когда таймер не превышает это число секунд. Нужны «Цвета срочности».", "等待中的分组进度条在计时器不超过此秒数时变为红色。需要开启“紧急程度颜色”。", "A barra de progresso de um grupo em espera fica vermelha quando o timer está nesse número de segundos ou menos. Precisa de Cores de urgência.", "La barra de progreso de un grupo en espera se vuelve roja cuando el temporizador está en estos segundos o menos. Necesita Colores de urgencia.", "Bilah kemajuan grup yang menunggu berubah merah saat timer sama dengan atau kurang dari jumlah detik ini. Perlu Warna urgensi.", "Bilah kamajuan grup nu ngantosan jadi beureum lamun timer sarua atawa kurang ti jumlah detik ieu. Perlu Warna urgénsi." },
    { "On: an alert on screen and a red Bags chip on the minimized bar when your free bag slots drop to the number below. Full bags are the most common way to lose loot.", "An: eine Warnung auf dem Bildschirm und ein roter Taschen-Chip auf der minimierten Leiste, wenn deine freien Taschenplätze auf die unten genannte Zahl sinken. Volle Taschen sind der häufigste Grund, Beute zu verlieren.", "Activé : une alerte à l'écran et un chip Sacs rouge sur la barre réduite quand vos emplacements libres tombent à ce nombre. Des sacs pleins sont la cause la plus fréquente de perte de butin.", "Attivo: un avviso a schermo e un chip Borse rosso sulla barra ridotta quando gli slot liberi delle borse scendono a questo numero. Le borse piene sono il modo più comune di perdere bottino.", "켜짐: 빈 가방 칸이 아래 숫자 이하로 떨어지면 화면 알림과 최소화 바의 빨간 가방 칩이 표시됩니다. 가방이 가득 차면 전리품을 잃기 가장 쉽습니다.", "オン：空きバッグ枠が下の数以下になると、画面に通知が出て、最小化バーに赤いバッグのチップが表示されます。バッグが満杯だと戦利品を失いやすくなります。", "Вкл.: при уменьшении свободных ячеек сумок до указанного числа на экране появится оповещение, а на свёрнутой панели — красный чип «Сумки». Полные сумки — самая частая причина потери добычи.", "开启：当空闲背包格数降到下方数值时，屏幕上会出现提醒，最小化栏上会显示红色背包标签。背包满是最常见的丢失战利品的原因。", "Ligado: um aviso na tela e um chip Bolsas vermelho na barra minimizada quando seus espaços livres caírem para o número abaixo. Bolsas cheias são a forma mais comum de perder saque.", "Activado: un aviso en pantalla y un chip Bolsas rojo en la barra minimizada cuando tus espacios libres bajen al número de abajo. Las bolsas llenas son la forma más común de perder botín.", "Aktif: peringatan di layar dan chip Tas merah di bilah minimize saat slot tas kosongmu turun ke jumlah di bawah. Tas penuh adalah cara paling umum kehilangan loot.", "Aktif: peringatan dina layar jeung chip Tas beureum dina bilah minimize lamun slot tas kosong turun ka jumlah di handap. Tas pinuh mangrupa cara nu paling sering ngaleungitkeun loot." },
    { "The bag space warning shows when this many bag slots or fewer are free. Needs Bag space warning.", "Die Taschenwarnung erscheint, wenn so viele Taschenplätze oder weniger frei sind. Benötigt Warnung bei vollen Taschen.", "L'alerte d'espace des sacs apparaît quand ce nombre d'emplacements ou moins est libre. Nécessite l'alerte d'espace des sacs.", "L'avviso spazio borse appare quando sono liberi questo numero di slot o meno. Richiede l'avviso spazio borse.", "가방 칸이 이 수 이하로 남으면 경고가 표시됩니다. '가방 공간 경고'가 필요합니다.", "空きバッグ枠がこの数以下になると警告を表示します。「バッグの空き警告」が必要です。", "Предупреждение появится, когда свободных ячеек станет не больше этого числа. Нужно «Предупреждение о месте в сумках».", "当空闲背包格数不多于此数时显示警告。需要开启“背包空间警告”。", "O aviso de espaço nas bolsas aparece quando este número de espaços ou menos estiver livre. Precisa de Aviso de espaço nas bolsas.", "El aviso de espacio en bolsas aparece cuando hay este número de espacios libres o menos. Necesita Aviso de espacio en bolsas.", "Peringatan ruang tas muncul saat slot kosong sama dengan atau kurang dari jumlah ini. Perlu Peringatan ruang tas.", "Peringatan rohangan tas muncul lamun slot kosong sarua atawa kurang ti jumlah ieu. Perlu Peringatan rohangan tas." },
    { "On: the XP line shows how many battles you need to reach the next level.", "An: Die XP-Zeile zeigt, wie viele Kämpfe du bis zum nächsten Level brauchst.", "Activé : la ligne XP indique combien de combats il faut pour atteindre le niveau suivant.", "Attivo: la riga XP mostra quante battaglie mancano al livello successivo.", "켜짐: XP 줄에 다음 레벨까지 필요한 전투 수를 표시합니다.", "オン：XP行に次のレベルまでに必要な戦闘数を表示します。", "Вкл.: строка XP показывает, сколько боёв нужно до следующего уровня.", "开启：XP 行显示到达下一级还需多少场战斗。", "Ligado: a linha de XP mostra quantas batalhas faltam para o próximo nível.", "Activado: la línea de XP muestra cuántas batallas faltan para el siguiente nivel.", "Aktif: baris XP menampilkan berapa pertarungan lagi sampai level berikutnya.", "Aktif: baris XP mintonkeun sabaraha tarung deui nepi ka level saterusna." },
    { "On: the XP line shows your hero XP per hour over the last 10 minutes, with the session average next to it once the session is longer.", "An: Die XP-Zeile zeigt deine Helden-XP pro Stunde in den letzten 10 Minuten; sobald die Sitzung länger ist, steht daneben der Sitzungsdurchschnitt.", "Activé : la ligne XP affiche votre XP héros par heure sur les 10 dernières minutes, avec la moyenne de session à côté une fois la session plus longue.", "Attivo: la riga XP mostra l'XP eroe all'ora degli ultimi 10 minuti, con accanto la media della sessione quando la sessione è più lunga.", "켜짐: XP 줄에 최근 10분 동안의 영웅 시간당 XP를 표시하며, 세션이 길어지면 세션 평균도 함께 표시합니다.", "オン：XP行に直近10分間の英雄の時間あたりXPを表示し、セッションが長くなると横にセッション平均を表示します。", "Вкл.: строка XP показывает XP героя в час за последние 10 минут; когда сессия длиннее, рядом выводится среднее за сессию.", "开启：XP 行显示最近 10 分钟的英雄每小时 XP；会话时间较长后，旁边还会显示会话平均值。", "Ligado: a linha de XP mostra seu XP de herói por hora nos últimos 10 minutos, com a média da sessão ao lado quando a sessão já for longa.", "Activado: la línea de XP muestra tu XP de héroe por hora en los últimos 10 minutos, con el promedio de la sesión al lado cuando la sesión es más larga.", "Aktif: baris XP menampilkan XP pahlawan per jam selama 10 menit terakhir, dengan rata-rata sesi di sebelahnya jika sesi sudah cukup lama.", "Aktif: baris XP mintonkeun XP pahlawan per jam salila 10 menit panungtungan, kalawan rata-rata sési di sebelahna lamun sési geus lila." },
    { "On: the XP line shows how long until the next level at your current XP per hour.", "An: Die XP-Zeile zeigt, wie lange es bei deiner aktuellen XP pro Stunde bis zum nächsten Level dauert.", "Activé : la ligne XP indique le temps restant avant le niveau suivant au rythme actuel d'XP par heure.", "Attivo: la riga XP mostra quanto manca al livello successivo al ritmo attuale di XP all'ora.", "켜짐: XP 줄에 현재 시간당 XP 기준으로 다음 레벨까지 걸리는 시간을 표시합니다.", "オン：XP行に、現在の時間あたりXPで次のレベルまでの時間を表示します。", "Вкл.: строка XP показывает, сколько осталось до следующего уровня при текущем XP в час.", "开启：XP 行按当前每小时 XP 显示距离下一级还需多久。", "Ligado: a linha de XP mostra quanto tempo falta para o próximo nível no seu ritmo atual de XP por hora.", "Activado: la línea de XP muestra cuánto falta para el siguiente nivel al ritmo actual de XP por hora.", "Aktif: baris XP menampilkan berapa lama lagi sampai level berikutnya dengan XP per jam saat ini.", "Aktif: baris XP mintonkeun sabaraha lila deui nepi ka level saterusna dina XP per jam ayeuna." },
    { "On: the XP line shows how much rested XP you have, in percent of the level.", "An: Die XP-Zeile zeigt, wie viel erholte XP du hast, in Prozent des Levels.", "Activé : la ligne XP indique votre XP reposé, en pourcentage du niveau.", "Attivo: la riga XP mostra quanto XP riposato hai, in percentuale del livello.", "켜짐: XP 줄에 휴식 XP를 레벨의 백분율로 표시합니다.", "オン：XP行に休息XPを、レベルに対する割合で表示します。", "Вкл.: строка XP показывает, сколько у вас XP отдыха, в процентах от уровня.", "开启：XP 行以本级百分比显示你的充分休息 XP。", "Ligado: a linha de XP mostra quanto XP descansado você tem, em porcentagem do nível.", "Activado: la línea de XP muestra cuánto XP descansado tienes, en porcentaje del nivel.", "Aktif: baris XP menampilkan XP istirahat yang kamu punya, dalam persen dari level.", "Aktif: baris XP mintonkeun XP istirahat anjeun, dina persén tina level." },
    { "On: the XP line warns, and a chat message appears once, when your hunter pet has reached your level and gains no more XP.", "An: Die XP-Zeile warnt, und einmal erscheint eine Chatnachricht, wenn dein Jäger-Pet dein Level erreicht hat und keine XP mehr erhält.", "Activé : la ligne XP avertit, et un message apparaît une fois, quand votre familier de chasseur a atteint votre niveau et ne gagne plus d'XP.", "Attivo: la riga XP avvisa, e compare una volta un messaggio in chat, quando il tuo famiglio cacciatore ha raggiunto il tuo livello e non guadagna più XP.", "켜짐: 사냥꾼 펫이 내 레벨에 도달해 경험치를 더 얻지 못하면 XP 줄에 경고하고 채팅 메시지가 한 번 표시됩니다.", "オン：猟師のペットがあなたのレベルに達して経験値を得られなくなると、XP行に警告が出て、チャットに一度メッセージが表示されます。", "Вкл.: строка XP предупреждает, а в чат один раз выводится сообщение, когда питомец охотника достиг вашего уровня и больше не получает опыт.", "开启：当猎人宠物达到你的等级、不再获得经验时，XP 行会发出警告，并在聊天中提示一次。", "Ligado: a linha de XP avisa, e uma mensagem aparece no chat uma vez, quando o mascote do seu caçador chegou ao seu nível e não ganha mais XP.", "Activado: la línea de XP avisa, y aparece un mensaje en el chat una vez, cuando la mascota de tu cazador alcanza tu nivel y ya no gana XP.", "Aktif: baris XP memberi peringatan, dan pesan di chat muncul sekali, saat peliharaan pemburumu sudah setara levelmu dan tidak lagi dapat XP.", "Aktif: baris XP ngasih peringatan, jeung pesen di chat muncul sakali, lamun piaraan pamburu geus sarua jeung level anjeun jeung teu meunang XP deui." },
    { "On: the XP line shows the gold you loot per hour this session, with the same prices as the gold summary.", "An: Die XP-Zeile zeigt das Gold pro Stunde, das du in dieser Sitzung plünderst, mit denselben Preisen wie in der Goldübersicht.", "Activé : la ligne XP affiche l'or par heure que vous récoltez pendant cette session, avec les mêmes prix que le résumé de l'or.", "Attivo: la riga XP mostra l'oro all'ora raccolto in questa sessione, con gli stessi prezzi del riepilogo dell'oro.", "켜짐: XP 줄에 이번 세션의 시간당 획득 골드를 골드 요약과 같은 가격으로 표시합니다.", "オン：XP行に、このセッションで獲得した時間あたりのゴールドを、ゴールド集計と同じ価格で表示します。", "Вкл.: строка XP показывает золото в час, полученное за эту сессию, по тем же ценам, что и в сводке золота.", "开启：XP 行显示本次会话每小时获得的金币，价格与金币摘要相同。", "Ligado: a linha de XP mostra o ouro que você saqueia por hora nesta sessão, com os mesmos preços do resumo de ouro.", "Activado: la línea de XP muestra el oro que saqueas por hora en esta sesión, con los mismos precios del resumen de oro.", "Aktif: baris XP menampilkan emas yang kamu loot per jam di sesi ini, dengan harga yang sama seperti ringkasan emas.", "Aktif: baris XP mintonkeun emas nu di-loot per jam dina sési ieu, kalawan harga nu sarua jeung ringkasan emas." },
    { "On: standing still for more than 2 minutes (no moving, fighting, casting, looting or XP) is left out of XP per hour, time to level and the goal pace. Off: the whole session time counts.", "An: Stillstehen für mehr als 2 Minuten (keine Bewegung, kein Kampf, kein Zaubern, Plündern oder XP) wird aus XP pro Stunde, Zeit bis zum Level und dem Zieltempo herausgerechnet. Aus: die ganze Sitzungszeit zählt.", "Activé : rester immobile plus de 2 minutes (sans bouger, combattre, lancer de sort, piller ou gagner d'XP) est exclu de l'XP par heure, du temps avant le niveau et du rythme de l'objectif. Désactivé : tout le temps de session compte.", "Attivo: restare fermi per più di 2 minuti (senza muoversi, combattere, lanciare, saccheggiare o guadagnare XP) è escluso dall'XP all'ora, dal tempo al livello e dal ritmo dell'obiettivo. Disattivo: conta tutto il tempo della sessione.", "켜짐: 2분 넘게 가만히 있으면(이동, 전투, 시전, 전리품, 경험치 없음) 시간당 XP, 레벨까지 시간, 목표 속도에서 제외됩니다. 꺼짐: 세션 전체 시간이 계산됩니다.", "オン：2分以上静止している時間（移動、戦闘、詠唱、戦利品、XPなし）は、時間あたりXP、レベルまでの時間、目標のペースから除外されます。オフ：セッション全体の時間が数えられます。", "Вкл.: стояние на месте больше 2 минут (без движения, боя, заклинаний, добычи и опыта) не учитывается в XP в час, времени до уровня и темпе цели. Выкл.: учитывается всё время сессии.", "开启：静止超过 2 分钟（不移动、不战斗、不施法、不拾取、不获得经验）的时间不计入每小时 XP、升级时间和目标进度。关闭：整个会话时间都计算在内。", "Ligado: ficar parado por mais de 2 minutos (sem andar, lutar, conjurar, saquear ou ganhar XP) fica fora do XP por hora, do tempo até o nível e do ritmo da meta. Desligado: todo o tempo da sessão conta.", "Activado: estar quieto más de 2 minutos (sin moverte, luchar, lanzar, saquear ni ganar XP) queda fuera del XP por hora, del tiempo hasta el nivel y del ritmo de la meta. Desactivado: cuenta todo el tiempo de la sesión.", "Aktif: diam lebih dari 2 menit (tidak bergerak, bertarung, merapal, looting, atau dapat XP) tidak dihitung di XP per jam, waktu ke level, dan laju target. Nonaktif: seluruh waktu sesi dihitung.", "Aktif: diam leuwih ti 2 menit (teu gerak, tarung, ngucapkeun mantra, loot, atawa meunang XP) teu diitung dina XP per jam, waktu ka level, jeung laju target. Nonaktif: sakabeh waktu sési diitung." },
    { "On: when you level up, a message appears on screen and a sound plays.", "An: Wenn du aufsteigst, erscheint eine Nachricht auf dem Bildschirm und ein Ton wird abgespielt.", "Activé : quand vous montez de niveau, un message s'affiche à l'écran et un son se joue.", "Attivo: quando sali di livello, compare un messaggio a schermo e viene riprodotto un suono.", "켜짐: 레벨업하면 화면에 메시지가 나타나고 소리가 재생됩니다.", "オン：レベルアップすると画面にメッセージが表示され、音が鳴ります。", "Вкл.: при повышении уровня на экране появляется сообщение и проигрывается звук.", "开启：升级时屏幕上会出现提示，并播放声音。", "Ligado: quando você sobe de nível, aparece uma mensagem na tela e toca um som.", "Activado: al subir de nivel aparece un mensaje en pantalla y suena un sonido.", "Aktif: saat kamu naik level, pesan muncul di layar dan suara diputar.", "Aktif: lamun naek level, pesen muncul dina layar jeung sora diputer." },
    { "On: a message appears once per level when you are only a few battles away from the next level.", "An: Einmal pro Level erscheint eine Nachricht, wenn du nur noch wenige Kämpfe vom nächsten Level entfernt bist.", "Activé : un message apparaît une fois par niveau quand il ne vous reste que quelques combats avant le niveau suivant.", "Attivo: compare un messaggio una volta per livello quando mancano solo poche battaglie al livello successivo.", "켜짐: 다음 레벨까지 전투가 몇 번 남았을 때 레벨마다 한 번 메시지가 표시됩니다.", "オン：次のレベルまで戦闘があと数回になると、レベルごとに一度メッセージが表示されます。", "Вкл.: один раз на уровень появляется сообщение, когда до следующего уровня остаётся всего несколько боёв.", "开启：每级一次，当距离下一级只剩几场战斗时显示提示。", "Ligado: uma mensagem aparece uma vez por nível quando faltam só algumas batalhas para o próximo nível.", "Activado: aparece un mensaje una vez por nivel cuando solo faltan unas pocas batallas para el siguiente nivel.", "Aktif: pesan muncul sekali per level saat kamu hanya tinggal beberapa pertarungan dari level berikutnya.", "Aktif: pesen muncul sakali per level lamun ngan sababaraha tarung deui nepi ka level saterusna." },
    { "How many battles from the next level the alert shows. Needs Alert when close to level.", "Wie viele Kämpfe vor dem nächsten Level die Warnung erscheint. Benötigt Warnung kurz vor dem Level.", "À combien de combats du niveau suivant l'alerte apparaît. Nécessite l'alerte proche du niveau.", "A quante battaglie dal livello successivo appare l'avviso. Richiede l'avviso vicino al livello.", "다음 레벨까지 몇 번 남았을 때 알림을 표시할지 정합니다. '레벨 근접 시 알림'이 필요합니다.", "次のレベルまで何戦のときに通知するかを設定します。「レベル直前に通知」が必要です。", "За сколько боёв до следующего уровня показывать оповещение. Нужно «Оповещение при близости к уровню».", "距离下一级还剩多少场战斗时显示提醒。需要开启“接近升级时提醒”。", "Quantas batalhas faltam para o próximo nível para o alerta aparecer. Precisa de Alerta perto do nível.", "Cuántas batallas faltan para el siguiente nivel para que aparezca el aviso. Necesita Alerta cerca del nivel.", "Berapa pertarungan lagi sampai level berikutnya saat peringatan muncul. Perlu Peringatan dekat level.", "Sabaraha tarung deui nepi ka level saterusna nalika peringatan muncul. Perlu Peringatan deukeut level." },
    { "How much gold to loot this session, for example 500, then press Enter. Leave empty to have no gold goal.", "Wie viel Gold du in dieser Sitzung plünderst, z. B. 500, dann Enter drücken. Leer lassen, um kein Golfziel zu setzen.", "Combien d'or récolter pendant cette session, par exemple 500, puis Entrée. Laissez vide pour ne pas avoir d'objectif d'or.", "Quanto oro saccheggiare in questa sessione, ad esempio 500, poi Invio. Lascia vuoto per non avere un obiettivo di oro.", "이번 세션에서 얻을 골드(예: 500)를 입력하고 Enter를 누르세요. 비워 두면 골드 목표가 없습니다.", "このセッションで獲得するゴールド（例: 500）を入力して Enter を押してください。空欄ならゴールド目標はありません。", "Сколько золота собрать за эту сессию, например 500, затем Enter. Оставьте пустым, чтобы не задавать цель по золоту.", "本次会话要获得的金币（例如 500），然后按回车。留空则没有金币目标。", "Quanto ouro saquear nesta sessão, por exemplo 500, depois Enter. Deixe vazio para não ter meta de ouro.", "Cuánto oro saquear en esta sesión, por ejemplo 500, luego Enter. Déjalo vacío para no tener meta de oro.", "Berapa emas yang di-loot di sesi ini, misalnya 500, lalu Enter. Kosongkan jika tidak ada target emas.", "Sabaraha emas nu di-loot dina sési ieu, contona 500, terus Enter. Kosongkeun lamun teu aya target emas." },
    { "The level to reach, for example 40, then press Enter. Leave empty to have no level goal.", "Das Level, das du erreichen willst, z. B. 40, dann Enter drücken. Leer lassen, um kein Levelziel zu setzen.", "Le niveau à atteindre, par exemple 40, puis Entrée. Laissez vide pour ne pas avoir d'objectif de niveau.", "Il livello da raggiungere, ad esempio 40, poi Invio. Lascia vuoto per non avere un obiettivo di livello.", "도달할 레벨(예: 40)을 입력하고 Enter를 누르세요. 비워 두면 레벨 목표가 없습니다.", "到達するレベル（例: 40）を入力して Enter を押してください。空欄ならレベル目標はありません。", "Уровень, которого нужно достичь, например 40, затем Enter. Оставьте пустым, чтобы не задавать цель по уровню.", "要达到的等级（例如 40），然后按回车。留空则没有等级目标。", "O nível a alcançar, por exemplo 40, depois Enter. Deixe vazio para não ter meta de nível.", "El nivel a alcanzar, por ejemplo 40, luego Enter. Déjalo vacío para no tener meta de nivel.", "Level yang ingin dicapai, misalnya 40, lalu Enter. Kosongkan jika tidak ada target level.", "Level nu rék dihontong, contona 40, terus Enter. Kosongkeun lamun teu aya target level." },
    { "A Mining or Herbalism skill to reach, for example mining 300 or herb 225, then press Enter. Leave empty to have no skill goal. The time estimate starts after your first skill-up.", "Ein Bergbau- oder Kräuterkunde-Skill, den du erreichen willst, z. B. Bergbau 300 oder Kräuter 225, dann Enter. Leer lassen für kein Skillziel. Die Zeitschätzung beginnt nach deinem ersten Skill-Anstieg.", "Une compétence de minage ou d'herboristerie à atteindre, par exemple minage 300 ou herboristerie 225, puis Entrée. Laissez vide pour ne pas avoir d'objectif de compétence. L'estimation de temps commence après votre premier gain de compétence.", "Un'abilità di Mining o Erboristeria da raggiungere, ad esempio mining 300 o herb 225, poi Invio. Lascia vuoto per non avere un obiettivo di abilità. La stima del tempo inizia dopo il primo aumento di abilità.", "도달할 채광 또는 약초 기술(예: 채광 300, 약초 225)을 입력하고 Enter를 누르세요. 비워 두면 기술 목표가 없습니다. 시간 예측은 첫 기술 상승 후부터 시작됩니다.", "到達する採掘または薬草学のスキル（例: 採掘 300、薬草 225）を入力して Enter を押してください。空欄ならスキル目標はありません。時間の予測は最初のスキル上昇後に始まります。", "Навык добычи или травничества, которого нужно достичь, например mining 300 или herb 225, затем Enter. Оставьте пустым, чтобы не задавать цель по навыку. Оценка времени начинается после первого повышения навыка.", "要达到的采矿或草药学技能（例如 mining 300 或 herb 225），然后按回车。留空则没有技能目标。时间估计在第一次技能提升后开始。", "Uma habilidade de Mineração ou Herborismo a alcançar, por exemplo mining 300 ou herb 225, depois Enter. Deixe vazio para não ter meta de habilidade. A estimativa de tempo começa após seu primeiro aumento de habilidade.", "Una habilidad de Minería o Herboristería a alcanzar, por ejemplo mining 300 o herb 225, luego Enter. Déjalo vacío para no tener meta de habilidad. La estimación de tiempo empieza tras tu primera subida de habilidad.", "Skill Mining atau Herbalism yang ingin dicapai, misalnya mining 300 atau herb 225, lalu Enter. Kosongkan jika tidak ada target skill. Perkiraan waktu mulai setelah kenaikan skill pertama.", "Skill Mining atawa Herbalism nu rék dihontong, contona mining 300 atawa herb 225, terus Enter. Kosongkeun lamun teu aya target skill. Perkiraan waktu mimiti sanggeus naek skill kahiji." },
    { "Optional: the hours you give yourself to reach the goals above, for example 2 or 1.5. The goal line turns orange when you are tight on time and red when you are behind, and the time left is shown in the goal text. Leave empty for no time limit.", "Optional: die Stunden, die du dir zum Erreichen der Ziele oben gibst, z. B. 2 oder 1,5. Die Zielzeile wird orange, wenn es knapp wird, und rot, wenn du hinterherhinkst; die verbleibende Zeit steht im Zieltext. Leer lassen für kein Zeitlimit.", "Facultatif : les heures que vous vous donnez pour atteindre les objectifs ci-dessus, par exemple 2 ou 1,5. La ligne d'objectif devient orange si le temps presse et rouge si vous êtes en retard ; le temps restant s'affiche dans le texte. Laissez vide pour aucune limite de temps.", "Facoltativo: le ore che ti dai per raggiungere gli obiettivi qui sopra, ad esempio 2 o 1,5. La riga dell'obiettivo diventa arancione quando il tempo stringe e rossa quando sei in ritardo; il tempo rimasto è mostrato nel testo. Lascia vuoto per nessun limite di tempo.", "선택 사항: 위 목표를 달성할 시간(예: 2 또는 1.5)입니다. 시간이 빠듯하면 목표 줄이 주황색, 뒤처지면 빨간색이 되며 남은 시간이 목표 글자에 표시됩니다. 비워 두면 시간 제한이 없습니다.", "任意：上の目標を達成するための時間（例: 2 または 1.5）。時間がきつくなると目標の行がオレンジ、遅れると赤になり、残り時間が目標の文字に表示されます。空欄なら時間制限はありません。", "Необязательно: часы, которые вы отводите на цели выше, например 2 или 1.5. Строка цели становится оранжевой, когда времени мало, и красной, когда вы отстаёте; оставшееся время выводится в тексте цели. Оставьте пустым, если без ограничения по времени.", "可选：你为上方目标留出的小时数，例如 2 或 1.5。时间紧张时目标行变为橙色，落后时变为红色，剩余时间显示在目标文字中。留空则没有时间限制。", "Opcional: as horas que você se dá para alcançar as metas acima, por exemplo 2 ou 1,5. A linha da meta fica laranja quando o tempo aperta e vermelha quando você está atrasado; o tempo restante aparece no texto da meta. Deixe vazio para não ter limite de tempo.", "Opcional: las horas que te das para lograr las metas de arriba, por ejemplo 2 o 1,5. La línea de la meta se vuelve naranja cuando el tiempo aprieta y roja cuando vas atrasado; el tiempo restante aparece en el texto de la meta. Déjalo vacío para no tener límite de tiempo.", "Opsional: jam yang kamu berikan untuk mencapai target di atas, misalnya 2 atau 1,5. Baris target berubah oranye saat waktu mepet dan merah saat tertinggal; sisa waktu ditampilkan di teks target. Kosongkan jika tanpa batas waktu.", "Opsional: jam nu anjeun pasihan pikeun ngahontong target di luhur, contona 2 atawa 1,5. Baris target jadi oranyé lamun waktu ngahimpit jeung beureum lamun ketinggalan; sésana waktu dipintonkeun dina téks target. Kosongkeun lamun euweuh wates waktu." },
    { "On: the smaller bar below the main bar shows your frame rate as fps:60.", "An: Die kleinere Leiste unter der Hauptleiste zeigt deine Bildrate als fps:60.", "Activé : la petite barre sous la barre principale affiche votre taux d'images sous la forme fps:60.", "Attivo: la barra più piccola sotto la barra principale mostra il frame rate come fps:60.", "켜짐: 기본 바 아래의 작은 바에 프레임 속도를 fps:60처럼 표시합니다.", "オン：メインバーの下の小さいバーに、フレームレートを fps:60 のように表示します。", "Вкл.: маленькая полоса под основной показывает частоту кадров как fps:60.", "开启：主栏下方的小栏以 fps:60 的形式显示帧率。", "Ligado: a barra menor abaixo da barra principal mostra sua taxa de quadros como fps:60.", "Activado: la barra pequeña bajo la barra principal muestra tu tasa de fotogramas como fps:60.", "Aktif: bilah kecil di bawah bilah utama menampilkan frame rate sebagai fps:60.", "Aktif: bilah leutik handapeun bilah utama mintonkeun frame rate salaku fps:60." },
    { "On: the smaller bar below the main bar shows your home latency in ms as H:45 (the connection to the realm). Green under 300, yellow under 500, and red and blinking at 500 or more.", "An: Die kleinere Leiste unter der Hauptleiste zeigt deine Heimat-Latenz in ms als H:45 (die Verbindung zum Realm). Grün unter 300, gelb unter 500, rot und blinkend ab 500.", "Activé : la petite barre sous la barre principale affiche votre latence maison en ms sous la forme H:45 (la connexion au royaume). Vert sous 300, jaune sous 500, rouge et clignotant à 500 ou plus.", "Attivo: la barra più piccola sotto la barra principale mostra la latenza di casa in ms come H:45 (la connessione al reame). Verde sotto 300, giallo sotto 500, rosso e lampeggiante da 500 in su.", "켜짐: 기본 바 아래의 작은 바에 홈 지연 시간을 ms로 H:45처럼 표시합니다(서버 연결). 300 미만은 초록, 500 미만은 노랑, 500 이상은 빨강과 깜빡임.", "オン：メインバーの下の小さいバーに、ホーム（レルム接続）のレイテンシをms単位で H:45 のように表示します。300未満は緑、500未満は黄、500以上は赤で点滅します。", "Вкл.: маленькая полоса под основной показывает задержку до дома в мс как H:45 (соединение с сервером). Зелёная до 300, жёлтая до 500, красная и мигающая от 500.", "开启：主栏下方的小栏以 H:45 的形式显示到服务器（分区）连接的延迟（毫秒）。300 以下为绿色，500 以下为黄色，500 及以上为红色并闪烁。", "Ligado: a barra menor abaixo da barra principal mostra sua latência até o reino em ms como H:45 (a conexão com o reino). Verde abaixo de 300, amarelo abaixo de 500, vermelho e piscando a partir de 500.", "Activado: la barra pequeña bajo la barra principal muestra tu latencia al reino en ms como H:45 (la conexión con el reino). Verde por debajo de 300, amarillo por debajo de 500, rojo y parpadeando desde 500.", "Aktif: bilah kecil di bawah bilah utama menampilkan latensi home dalam ms sebagai H:45 (koneksi ke realm). Hijau di bawah 300, kuning di bawah 500, merah dan berkedip dari 500.", "Aktif: bilah leutik handapeun bilah utama mintonkeun latensi home dina ms salaku H:45 (sambungan ka realm). Héjo handap 300, konéng handap 500, beureum jeung kedip ti 500." },
    { "On: the smaller bar below the main bar shows your world latency in ms as W:60 (the connection that carries movement and combat). Green under 300, yellow under 500, and red and blinking at 500 or more.", "An: Die kleinere Leiste unter der Hauptleiste zeigt deine Welt-Latenz in ms als W:60 (die Verbindung für Bewegung und Kampf). Grün unter 300, gelb unter 500, rot und blinkend ab 500.", "Activé : la petite barre sous la barre principale affiche votre latence monde en ms sous la forme W:60 (la connexion pour les déplacements et le combat). Vert sous 300, jaune sous 500, rouge et clignotant à 500 ou plus.", "Attivo: la barra più piccola sotto la barra principale mostra la latenza del mondo in ms come W:60 (la connessione per movimento e combattimento). Verde sotto 300, giallo sotto 500, rosso e lampeggiante da 500 in su.", "켜짐: 기본 바 아래의 작은 바에 월드 지연 시간을 ms로 W:60처럼 표시합니다(이동과 전투 연결). 300 미만은 초록, 500 미만은 노랑, 500 이상은 빨강과 깜빡임.", "オン：メインバーの下の小さいバーに、ワールド（移動と戦闘の接続）のレイテンシをms単位で W:60 のように表示します。300未満は緑、500未満は黄、500以上は赤で点滅します。", "Вкл.: маленькая полоса под основной показывает задержку до мира в мс как W:60 (соединение для движения и боя). Зелёная до 300, жёлтая до 500, красная и мигающая от 500.", "开启：主栏下方的小栏以 W:60 的形式显示世界连接（移动和战斗）的延迟（毫秒）。300 以下为绿色，500 以下为黄色，500 及以上为红色并闪烁。", "Ligado: a barra menor abaixo da barra principal mostra sua latência do mundo em ms como W:60 (a conexão de movimento e combate). Verde abaixo de 300, amarelo abaixo de 500, vermelho e piscando a partir de 500.", "Activado: la barra pequeña bajo la barra principal muestra tu latencia del mundo en ms como W:60 (la conexión de movimiento y combate). Verde por debajo de 300, amarillo por debajo de 500, rojo y parpadeando desde 500.", "Aktif: bilah kecil di bawah bilah utama menampilkan latensi dunia dalam ms sebagai W:60 (koneksi gerak dan tarung). Hijau di bawah 300, kuning di bawah 500, merah dan berkedip dari 500.", "Aktif: bilah leutik handapeun bilah utama mintonkeun latensi dunya dina ms salaku W:60 (sambungan gerak jeung tarung). Héjo handap 300, konéng handap 500, beureum jeung kedip ti 500." },
    { "On: a sound plays once when your home or world ping turns red (500 ms or more). It waits 20 seconds before it can play again. Only the pings shown on the bar count.", "An: Ein Ton spielt einmal, wenn dein Heimat- oder Welt-Ping auf rot springt (500 ms oder mehr). Er kann erst nach 20 Sekunden wieder spielen. Es zählen nur die auf der Leiste angezeigten Pings.", "Activé : un son se joue une fois quand votre ping maison ou monde passe au rouge (500 ms ou plus). Il ne peut rejouer qu'après 20 secondes. Seuls les pings affichés sur la barre comptent.", "Attivo: un suono viene riprodotto una volta quando il ping di casa o del mondo diventa rosso (500 ms o più). Può suonare di nuovo solo dopo 20 secondi. Contano solo i ping mostrati sulla barra.", "켜짐: 홈 또는 월드 핑이 빨강(500 ms 이상)이 되면 소리가 한 번 재생됩니다. 20초 후에야 다시 재생됩니다. 바에 표시된 핑만 적용됩니다.", "オン：ホームまたはワールドのpingが赤（500ms以上）になると、音が一度鳴ります。20秒たつまで再び鳴りません。バーに表示されているpingだけが対象です。", "Вкл.: звук проигрывается один раз, когда домашний или мировой пинг становится красным (500 мс и больше). Снова он сможет сыграть не раньше чем через 20 секунд. Учитываются только пинги, показанные на панели.", "开启：家园或世界延迟变为红色（500 毫秒或以上）时播放一次声音。20 秒后才会再次播放。只计算栏上显示的延迟。", "Ligado: um som toca uma vez quando seu ping de casa ou do mundo fica vermelho (500 ms ou mais). Ele só toca de novo depois de 20 segundos. Só contam os pings mostrados na barra.", "Activado: un sonido suena una vez cuando tu ping de casa o del mundo se pone en rojo (500 ms o más). Solo puede volver a sonar tras 20 segundos. Solo cuentan los pings mostrados en la barra.", "Aktif: suara diputar sekali saat ping home atau dunia menjadi merah (500 ms atau lebih). Suara hanya bisa diputar lagi setelah 20 detik. Hanya ping yang ditampilkan di bilah yang dihitung.", "Aktif: sora diputer sakali lamun ping home atawa dunya jadi beureum (500 ms atawa leuwih). Ngan bisa diputer deui sanggeus 20 detik. Ngan ping nu dipintonkeun dina bilah nu diitung." },
    { "While a shown ping is red, the sound plays right away and then repeats after this many seconds. Needs Sound when ping is red.", "Solange ein angezeigter Ping rot ist, spielt der Ton sofort und wiederholt sich danach nach dieser Anzahl Sekunden. Benötigt „Ton, wenn Ping rot ist“.", "Tant qu'un ping affiché est rouge, le son se joue immédiatement puis se répète après ce nombre de secondes. Nécessite « Son quand le ping est rouge ».", "Finché un ping mostrato è rosso, il suono viene riprodotto subito e poi si ripete dopo questo numero di secondi. Richiede \"Suono quando il ping è rosso\".", "표시된 핑이 빨간색인 동안 소리가 바로 재생되고, 이 초가 지나면 다시 반복됩니다. '핑이 빨간색일 때 소리'가 필요합니다.", "表示中のpingが赤の間は、すぐに音が鳴り、この秒数ごとに繰り返されます。「pingが赤のときの音」が必要です。", "Пока показанный пинг красный, звук проигрывается сразу, а затем повторяется через это число секунд. Нужен «Звук, когда пинг красный».", "显示的延迟为红色期间，声音立即播放，之后每隔此秒数重复。需要开启“延迟为红色时的声音”。", "Enquanto um ping mostrado estiver vermelho, o som toca logo e depois se repete após este número de segundos. Precisa de Som quando o ping está vermelho.", "Mientras un ping mostrado esté en rojo, el sonido suena enseguida y luego se repite tras estos segundos. Necesita Sonido cuando el ping está en rojo.", "Selama ping yang ditampilkan merah, suara langsung diputar lalu diulang setelah jumlah detik ini. Perlu Suara saat ping merah.", "Salila ping nu dipintonkeun beureum, sora langsung diputer terus diulang sanggeus jumlah detik ieu. Perlu Sora nalika ping beureum." },
}

for _, row in ipairs(rows) do
    for i, code in ipairs(codes) do
        local t = GT.locales[code]
        if type(t) ~= "table" then t = {}; GT.locales[code] = t end
        if t[row[1]] == nil then t[row[1]] = row[i + 1] end
    end
end
